# Extract imported symbol sets. Strip comments, normalise.
extract() {
  node -e '
    const fs=require("fs");
    let src=fs.readFileSync(process.argv[1],"utf8");
    // strip block+line comments crudely
    src=src.replace(/\/\*[\s\S]*?\*\//g,"").replace(/^\s*\/\/.*$/gm,"");
    const out=new Set();
    const re=/import\s+(type\s+)?([\s\S]*?)\s+from\s+["\x27]([^"\x27]+)["\x27]/g;
    let m;
    while((m=re.exec(src))){
      let clause=m[2].trim();
      const src2=m[3];
      // named braces
      const br=clause.match(/\{([\s\S]*)\}/);
      if(br){
        br[1].split(",").forEach(x=>{x=x.trim(); if(x) out.add(x.split(/\s+as\s+/)[0].trim()+"  <"+src2+">");});
        clause=clause.replace(/\{[\s\S]*\}/,"").replace(/,\s*$/,"").trim();
      }
      if(clause) clause.split(",").forEach(x=>{x=x.trim(); if(x&&x!=="type") out.add(x+"  <"+src2+">");});
    }
    [...out].sort().forEach(x=>console.log(x));
  ' "$1"
}
